public class HazardRoom : MonoBehaviour
{
	private List<HazardTrigger> triggerList = new List<HazardTrigger>();

	private Dictionary<Hazard.ActivationType, List<Hazard>> hazardDict = new Dictionary<Hazard.ActivationType, List<Hazard>>();

	private bool isActivated;

	private bool shutdown;

	private void Start()
	{
		Hazard[] componentsInChildren = GetComponentsInChildren<Hazard>();
		foreach (Hazard hazard in componentsInChildren)
		{
			if (!hazardDict.ContainsKey(hazard.activationType))
			{
				hazardDict[hazard.activationType] = new List<Hazard>();
			}
			hazardDict[hazard.activationType].Add(hazard);
			hazard.Disable();
		}
	}

	public void AddTrigger(HazardTrigger givenTrigger)
	{
		triggerList.Add(givenTrigger);
	}

	public void HazardTriggered(bool overrideShutdown = false)
	{
		if (shutdown && !overrideShutdown)
		{
			return;
		}
		if (isActivated)
		{
			shutdown = true;
			foreach (List<Hazard> value in hazardDict.Values)
			{
				foreach (Hazard item in value)
				{
					if (item != null)
					{
						item.Disable();
					}
				}
			}
			foreach (HazardTrigger trigger in triggerList)
			{
				if (trigger != null)
				{
					trigger.Disable();
				}
			}
		}
		else
		{
			foreach (KeyValuePair<Hazard.ActivationType, List<Hazard>> item2 in hazardDict)
			{
				foreach (Hazard item3 in item2.Value)
				{
					if (item3 != null)
					{
						item3.activationType = item2.Key;
						item3.Initialize();
					}
				}
			}
		}
		isActivated = !isActivated;
	}

	public void ForceShutdown()
	{
		isActivated = true;
		shutdown = false;
		HazardTriggered();
	}
}
