}
public static void ApplyGlobalMods(NumVarStatMod givenCD = null, NumVarStatMod givenWindup = null, NumVarStatMod givenExit = null, bool givenStatus = true)
{
if (givenCD != null)
{
CooldownMultiStat.Modify(givenCD, givenStatus);
}
if (givenWindup != null)
{
WindupMultiStat.Modify(givenWindup, givenStatus);
}
if (ExitMultiStat != null)
{
ExitMultiStat.Modify(givenExit, givenStatus);
}
}
public void RegisterSkill(bool makeAvailableToAI = true, bool addToCooldowns = true)
{
if (makeAvailableToAI)
{
parent.availableEnemySkillsDict[skillID] = this;
}
else
{
parent.availableEnemySkillsDict.Remove(skillID);
}
if (addToCooldowns)
{
parent.cooldownManager.Add(skillID, cooldownTime);
cooldownRef = parent.cooldownManager.cooldowns[skillID];
}
registered = true;
}
public void InitChargeSkillSettings(int maxCharges, float cooldownTime)
{
isChargeSkill = true;
cooldownRef.isChargeSkill = true;
cooldownRef.chargeCount = maxCharges;
cooldownRef.MaxChargeCount = maxCharges;
cooldownRef.remainingTimeStopwatchID = -1;
cooldownRef.MaxTime = cooldownTime;
}
public bool BaseSkillIsReady()
{
if (parent.CurrentDifficulty < requiredDifficultyLevel)
{
return false;
}
if (isChargeSkill)
{
return parent.cooldownManager.cooldowns[skillID].chargeCount > 0;
}
return parent.cooldownManager.CheckCooldown(skillID);
}
public virtual bool IsReady()
{
return BaseSkillIsReady();
}
public bool Transition(bool checkIsReady = true)
{
if (fsm.currentStateName.Contains(skillID) || (checkIsReady && !IsReady()))
{
return false;
}
fsm.ChangeState(skillID, allowSelfTransition: true);
return true;
}
public virtual void ExitTransition()
{
parent.HandleExitTransitions();
}
public void StartCooldown(float overrideValue = -1f)
{
if (!registered || (cooldownTime <= 0f && overrideValue <= 0f) || parent == null)
{
return;
}
if (isChargeSkill)
{
if (cooldownRef.chargeCount > 0)
{
cooldownRef.chargeCount--;
}
parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
}
else
{
parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
}
}
public override void OnEnter()
{
parent.enemySkillUseInProgress = true;
StartCooldown();
currentDiffValue = parent.DifficultyValue;
isLegendary = parent.IsLegendary;
UpdateTargetVector();
if (parent.closestTargetInfo != null)
{
parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
}
if (usePowerUpEffect)
{
ActivatePowerUpEffect(spellCastColor);
}
windupComplete = false;
exitQueued = false;
}
public override void Update()
{
if (!WindupCheck)
{
if (ChaosStopwatch.Check(windupStopwatchID))
{
ExecuteSkill();
}
else
{
WindupUpdate();
}
}
else if (exitQueued && ChaosStopwatch.Check(exitStopwatchID))
{
ExitTransition();
}
}
public override void OnExit()
{
parent.enemySkillUseInProgress = false;
if (usePowerUpEffect)
{
DeactivatePowerUpEffect();
}
}
public virtual void ActivatePowerUpEffect(Color color, Color? color2 = null, bool skipOutline = false)
{
if (!disablePowerUpEffect)
{
powerUpEffect = PoolManager.GetPoolItem<PowerUpEffect>();
if (parent.spriteRenderer != null)
{
powerUpEffect.Activate(parent.spriteRenderer.transform, color);
}
else
{
powerUpEffect.Activate(powerUpTrans ?? parent.transform, color);
}
if (!skipOutline)
{
parent.SetOutlineColor(color, color2);
}
if (playPowerUpAudio)
{
SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
}
}
}
public virtual void DeactivatePowerUpEffect(bool skipBreakEffect = false)
{
if (powerUpEffect != null)
{
powerUpEffect.Deactivate();
}
if (!disablePowerUpEffect)
{
if (!skipBreakEffect && parent.spriteRenderer.material.GetColor("_OutlineColor") == armorCastColor && !parent.currentStateName.Contains("Dead"))
{
PoolManager.GetPoolItem<ParticleEffect>("ArmorDissipateEffect").Emit(15, parent.transform.position);
}
parent.SetOutlineColor(Color.clear, Color.clear);
}
}
public virtual Vector2 UpdateTargetVector(bool updateInfo = false, bool useTransform = false)
{
if (updateInfo)
{
parent.UpdateTargetInfo();
}
if (parent.closestTargetInfo == null || (useTransform && (parent.closestTargetInfo.transform == null || parent.closestTargetInfo.hurtBoxTransform == null)))
{
targetVector = Vector2.zero;
}
else
{
ref Vector2 reference = ref targetVector;
Vector3 vector;
if (useTargetHurtBox)
{
vector = ((!useTransform) ? parent.closestTargetInfo.hurtBoxPosition : parent.closestTargetInfo.hurtBoxTransform.position);
}
else
{
vector = ((!useTransform) ? parent.closestTargetInfo.position : parent.closestTargetInfo.transform.position);
}
reference = vector;
targetVector = ((!useTargetHurtBox) ? (targetVector - (Vector2)parent.transform.position) : (targetVector - (Vector2)parent.hurtBoxTransform.position)).normalized;
}
return targetVector;
}
public virtual void WindupUpdate()
{
}
public virtual void ExecuteSkill()
{
windupComplete = true;
exitStopwatchID = ChaosStopwatch.Begin((!(exitTime >= 0f)) ? StdExitTime : exitTime);
exitQueued = true;
}
public virtual T ChaosInst<T>(GameObject givenPrefab, Vector2? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTransform = null)
{
return Globals.ChaosInst<T>(givenPrefab, parentTransform ?? parent.transform.parent, (!givenPosition.HasValue) ? ((Vector2)parent.transform.position) : givenPosition.Value, (!givenQuaternion.HasValue
}
}
