  kind: state
  own_name: Босс ветра, двойной рывок с торнадо
  tags: [boss, wind_boss, skill, dash]
  numbers:
    dash_duration: {value: 0.2, unit: с}
    dash_speed: {value: 50, unit: м/с}
    end_dash_speed: {value: 12, unit: м/с}
    dash_count: 2
    windup: {value: стандартный замах босса}
